-- Metadata and aggregate counts only; safe in a READ ONLY transaction.
-- No business RPCs are invoked. Function bodies are fingerprinted, not exported.
with relations as (
 select c.*,n.nspname from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname in ('public','private') and c.relkind in ('r','p','v','m')
), functions as (
 select p.*,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname in ('public','private')
)
select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('schema',nspname,'name',relname,'rls',relrowsecurity,'force_rls',relforcerowsecurity) order by nspname,relname) from relations where relkind in ('r','p')),
 'columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by c.relname,a.attnum) from relations c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where c.relkind in ('r','p')),
 'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'definition',pg_get_constraintdef(k.oid,true)) order by c.relname,k.conname) from pg_constraint k join relations c on c.oid=k.conrelid),
 'indexes',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',ic.relname,'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'definition',pg_get_indexdef(i.indexrelid)) order by c.relname,ic.relname) from pg_index i join relations c on c.oid=i.indrelid join pg_class ic on ic.oid=i.indexrelid),
 'policies',(select jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'check',with_check) order by tablename,policyname) from pg_policies where schemaname in ('public','private')),
 'functions',(select jsonb_agg(jsonb_build_object('schema',p.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'language',l.lanname,'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'body_md5',md5(replace(p.prosrc,E'\r\n',E'\n')),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by p.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from functions p join pg_language l on l.oid=p.prolang),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace fn on fn.oid=p.pronamespace where not t.tgisinternal and fn.nspname in ('public','private') and (n.nspname in ('public','private') or (n.nspname='auth' and c.relname='users'))),
 'views',(select jsonb_agg(jsonb_build_object('name',relname,'options',reloptions,'definition',pg_get_viewdef(oid,true)) order by relname) from relations where relkind='v'),
 'api_privileges',(select jsonb_agg(jsonb_build_object('role',role.rolname,'table',c.relname,'privilege',priv.privilege,'allowed',has_table_privilege(role.oid,c.oid,priv.privilege)) order by role.rolname,c.relname,priv.privilege) from relations c cross join pg_roles role cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('TRIGGER'),('REFERENCES')) priv(privilege) where role.rolname in ('anon','authenticated','service_role')),
 'fk_checks',(select jsonb_agg(jsonb_build_object('constraint',k.conname,'table',c.relname,'sql',format('select %L as constraint_name, count(*)::int as orphan_count from %I.%I child where %s and not exists (select 1 from %I.%I parent where %s)',k.conname,c.nspname,c.relname,cols.nonnull,pn.nspname,pc.relname,cols.matches)) order by c.relname,k.conname) from pg_constraint k join relations c on c.oid=k.conrelid join pg_class pc on pc.oid=k.confrelid join pg_namespace pn on pn.oid=pc.relnamespace cross join lateral (select string_agg(format('child.%I is not null',ca.attname),' and ' order by keys.ordinality) nonnull,string_agg(format('parent.%I = child.%I',pa.attname,ca.attname),' and ' order by keys.ordinality) matches from unnest(k.conkey,k.confkey) with ordinality keys(childnum,parentnum,ordinality) join pg_attribute ca on ca.attrelid=k.conrelid and ca.attnum=keys.childnum join pg_attribute pa on pa.attrelid=k.confrelid and pa.attnum=keys.parentnum) cols where k.contype='f'),
 'integrity',jsonb_build_object(
  'active_room_duplicates',(select count(*) from (select room_id from public.rental_agreements where status='active' group by room_id having count(*)>1) x),
  'active_tenant_duplicates',(select count(*) from (select tenant_id from public.rental_agreements where status='active' group by tenant_id having count(*)>1) x),
  'closed_without_date',(select count(*) from public.rental_agreements where status<>'active' and closed_on is null),
  'successful_payment_duplicates',(select count(*) from (select invoice_id from public.transactions where status='succeeded' and kind='rent' group by invoice_id having count(*)>1) x),
  'paid_without_successful_payment',(select count(*) from public.invoices i where i.status='paid' and not exists(select 1 from public.transactions t where t.invoice_id=i.id and t.status='succeeded')),
  'pending_with_successful_payment',(select count(*) from public.invoices i where i.status<>'paid' and exists(select 1 from public.transactions t where t.invoice_id=i.id and t.status='succeeded')),
  'active_recurring_on_closed_agreement',(select count(*) from public.recurring_invoices ri join public.rental_agreements a on a.id=ri.agreement_id where ri.active and a.status<>'active')
 ),
 'counts',jsonb_build_object('auth_users',(select count(*) from auth.users),'profiles',(select count(*) from public.profiles),'properties',(select count(*) from public.properties),'rooms',(select count(*) from public.rooms),'tenants',(select count(*) from public.tenants),'agreements',(select count(*) from public.rental_agreements),'invoices',(select count(*) from public.invoices),'transactions',(select count(*) from public.transactions),'facilities',(select count(*) from public.facilities)),
 'facility_codes',(select jsonb_agg(code order by code) from public.facilities),
 'api_roles',(select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb) order by rolname) from pg_roles where rolname in ('anon','authenticated','service_role')),
 'schema_access',(select jsonb_agg(jsonb_build_object('role',r.rolname,'schema',n.nspname,'usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE')) order by r.rolname,n.nspname) from pg_roles r cross join pg_namespace n where r.rolname in ('anon','authenticated','service_role') and n.nspname in ('public','private')),
 'unindexed_foreign_keys',coalesce((select jsonb_agg(jsonb_build_object('table',c.relname,'constraint',k.conname,'columns',k.conkey) order by c.relname,k.conname) from pg_constraint k join relations c on c.oid=k.conrelid where k.contype='f' and not exists(select 1 from pg_index i where i.indrelid=k.conrelid and i.indisvalid and i.indpred is null and i.indkey[0]=k.conkey[1])),'[]'::jsonb)
) as catalogue;
